import sys

MOD = 1000000007

# Precompute factorials and inverse factorials up to 10
MAX_N = 10
fact = [1] * (MAX_N + 1)
for i in range(1, MAX_N + 1):
    fact[i] = fact[i-1] * i % MOD

inv_fact = [1] * (MAX_N + 1)
inv_fact[MAX_N] = pow(fact[MAX_N], MOD - 2, MOD)
for i in range(MAX_N - 1, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m = int(data[0])
    s = str(m)
    n = len(s)

    # DP[pos][tight][count] = number of ways
    dp = [[[0] * 11 for _ in range(2)] for __ in range(n + 1)]
    dp[0][1][0] = 1

    for pos in range(n):
        limit = int(s[pos])
        for tight in range(2):
            for cnt in range(11):
                val = dp[pos][tight][cnt]
                if val == 0:
                    continue
                max_d = limit if tight else 9
                for dig in range(0, max_d + 1):
                    ntight = 1 if (tight and dig == max_d) else 0
                    ncnt = cnt + (1 if dig == 4 or dig == 7 else 0)
                    if ncnt <= 10:
                        dp[pos+1][ntight][ncnt] = (dp[pos+1][ntight][ncnt] + val) % MOD

    total_counts = [0] * 11
    for tight in range(2):
        for cnt in range(11):
            total_counts[cnt] = (total_counts[cnt] + dp[n][tight][cnt]) % MOD

    # Exclude the number 0
    total_counts[0] = (total_counts[0] - 1) % MOD

    ans = 0
    for c in range(1, 11):
        F_c = total_counts[c]
        if F_c == 0:
            continue
        available = total_counts[:]
        available[c] = (available[c] - 1) % MOD

        dp2 = [[0] * 7 for _ in range(11)]
        dp2[0][0] = 1

        for k in range(11):
            cnt_k = available[k]
            max_take = min(cnt_k, 6)
            if max_take == 0:
                continue
            # Precompute combinations for this k
            combs = [nCr(cnt_k, t) for t in range(max_take + 1)]
            new_dp = [row[:] for row in dp2]
            for s_val in range(11):
                for j in range(7):
                    cur = dp2[s_val][j]
                    if cur == 0:
                        continue
                    for t in range(1, max_take + 1):
                        ns = s_val + t * k
                        nj = j + t
                        if ns <= 10 and nj <= 6:
                            new_dp[ns][nj] = (new_dp[ns][nj] + cur * combs[t]) % MOD
            dp2 = new_dp

        sum_ways = 0
        for s_val in range(c):
            sum_ways = (sum_ways + dp2[s_val][6]) % MOD

        contrib = F_c * sum_ways % MOD * fact[6] % MOD
        ans = (ans + contrib) % MOD

    print(ans)

if __name__ == "__main__":
    solve()
